    /// <summary>
    /// Finds a specified record in the <c>METClaimSetup</c> table.
    /// </summary>
    /// <param name="_recId">
    /// The record ID of the record to find.
    /// </param>
    /// <param name="_forUpdate">
    /// A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <param name="_concurrencyModel">
    /// The concurrency model option to use when the record is read; optional.
    /// </param>
    /// <returns>
    /// A record in the <c>METClaimSetup</c> table; otherwise, an empty record.
    /// </returns>
    public static METClaimSetup find(
        RecId              _recId,
        boolean            _forUpdate = false,
        ConcurrencyModel   _concurrencyModel = ConcurrencyModel::Auto)
    {
        METClaimSetup claimSetup;

        claimSetup.selectForUpdate(_forUpdate);

        if (_forUpdate  && _concurrencyModel != ConcurrencyModel::Auto)
        {
            claimSetup.concurrencyModel(_concurrencyModel);
        }

        select firstonly claimSetup
            where claimSetup.RecId == _recId;

        return claimSetup;
    }

    /// <summary>
    /// Finds a record in the <c>METClaimSetup</c> table that has specified <c>METComponent</c> and <c>VendAccount</c>
    /// value.
    /// </summary>
    /// <param name="_component">
    /// A value of the <c>METComponent</c> field.
    /// </param>
    /// <param name="_supplier">
    /// A value of the <c>VendAccount</c> field.
    /// </param>
    /// <param name="_siteId">
    /// A value of the <c>InventSiteId</c> field.
    /// </param>
    /// <returns>
    /// A <c>METClaimSetup</c> record.
    /// </returns>
    public static METClaimSetup findByComponentSupplier(
        METComponent      _component,
        VendAccount       _supplier,
        InventSiteId      _siteId = '')
    {
        METClaimSetup claimSetup;

        select firstonly claimSetup
            where claimSetup.Component      == _component
               && claimSetup.Supplier       == _supplier
               && claimSetup.SiteId         == _siteId;

        if (!claimSetup)
        {
            select firstonly claimSetup
                where claimSetup.Component      == _component
                   && claimSetup.Supplier       == _supplier
                   && claimSetup.SiteId         == '';
        }

        return claimSetup;
    }
